grep -rln "migration" --include=declared-checks.json packs .claudinite/local | head; echo "=== ids mentioning migration ==="; node -e "
const fs=require('fs'),path=require('path');
function walk(d,out=[]){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name); if(e.isDirectory()){if(e.name==='node_modules'||e.name==='.git')continue; walk(p,out);} else if(e.name==='declared-checks.json') out.push(p);} return out;}
for(const f of [...walk('packs'), ...walk('.claudinite/local')]){
  const j=JSON.parse(fs.readFileSync(f,'utf8')); const arr=Array.isArray(j)?j:(j.checks||[]);
  for(const c of arr) if(/migration|materializ|appliesTo|probe|path/i.test(JSON.stringify(c))) console.log(f.replace('/declared-checks.json',''), '->', c.id);
}
"

